import { ConflictError } from "@zudojs/errors";
import { schema } from "@zudojs/schema";

const NewTask = schema.object({ title: schema.string().trim().min(3) });

class TaskService {
  tasks = new Map();
  nextId = 1;

  create(input) {
    const data = NewTask.parse(input);
    if ([...this.tasks.values()].some((t) => t.title === data.title)) {
      throw new ConflictError(`A task called "${data.title}" already exists`);
    }
    const task = { id: this.nextId, ...data };
    this.nextId += 1;
    this.tasks.set(task.id, task);
    return task;
  }
}

const service = new TaskService();
service.create({ title: "Buy milk" });
for (const input of [{ title: " Buy milk " }, { title: "no" }, { title: "Walk dog" }]) {
  try {
    console.log(service.create(input).id);
  } catch (error) {
    console.log(error.statusCode);
  }
}

