import { ConflictError } from "@zudojs/errors";
import { schema } from "@zudojs/schema";

const NewTask = schema.object({ title: schema.string().trim().min(3).max(100) });
const service = {
  tasks: [],
  create(input) {
    const data = NewTask.parse(input);
    if (this.tasks.some((t) => t.title === data.title)) throw new ConflictError("Duplicate title");
    const task = { id: this.tasks.length + 1, ...data };
    this.tasks.push(task);
    return task;
  },
};

function createMany(inputs) {
  const out = [];
  for (const input of inputs) {
    try {
      out.push(service.create(input).id);
    } catch (error) {
      out.push(error.code);
    }
  }
  return out;
}

console.log(createMany([{ title: "Buy milk" }, { title: "Buy milk " }, { title: 7 }, { title: "Walk dog" }]));
